%% Toolbox paths

path_toolbox_sitau = '..\Toolbox_sitau2\';
path_bin_folder = 'BIN_256\'; % SITAU.XML de esta carpeta determina 4 u 8 bases.

addpath(path_toolbox_sitau)

clc


%% OPEN THE SYSTEM
% (emulates_sitau2 = false) -> No Hardware mode disabled, it is necessary
%       to connect the hardware to use the library.
% (emulates_sitau2 = true) -> No Hardware mode activated, it is not
%       necessary to connect the hardware to use the library, the
%       library functions do not access the hardware, the data received by
%       the hardware is synthetically generated by the library.
emulates_sitau2 = false; % Prueba con hardware real y transporte PCIe.

result = OpenSys ([path_toolbox_sitau path_bin_folder], '192.168.2.10', 55902, 50460, 1, emulates_sitau2);
if (result < 0)
    CloseSys();
    return;
end

%% SYSTEM CONFIGURATION
xmlFile = 'SITAU2_PCIe_NOISE.XML';

try % Valida el mismo formato MC antes de configurar el equipo.
    [valid, withWarnings, performance] = Validate_XMLConfig(xmlFile, ST2_GetChannelsNumber(), 1); % Usa los canales de BASES_NUMBER y el enlace de OpenSys.
catch validation_error % No deja el sistema abierto si el XML es incompatible.
    CloseSys(); % Libera la conexion antes de informar el error de configuracion.
    rethrow(validation_error); % Mantiene el mensaje y la linea de la validacion.
end % Fin de validacion previa.
result = FUS_LoadXMLFileConfig(xmlFile);

if (result < 0)
    CloseSys();
    return;
end

try % Contrasta las dimensiones que realmente aplico la DLL.
    Validate_LoadedMCConfig(performance); % Detecta XML ignorado, DLL antigua o rafagas distintas.
catch validation_error % No inicia adquisicion con una configuracion diferente de la solicitada.
    CloseSys(); % Cierra la configuracion rechazada antes de volver a intentarlo.
    rethrow(validation_error); % Muestra la dimension que no coincide.
end % Fin de comprobacion posterior a la carga.

result = ST2_SetPulseAmplitude(30);
if (result < 0)
    CloseSys();
    return;
end




%% Get parameters from system

burst_number    = ST2_GetBurstsNumber();
acquisition_mode_continuous = ST2_GetAcquisitionMode();
% El tamano de una rafaga se calcula abajo con las dimensiones reales.
n_samples =     ST2_GetAScanDataNumber();
n_channels=     ST2_GetProbeElementNumber();
n_images_burst= ST2_GetAcquisitionsBurstNumber();
n_focal_law = ST2_GetFocalLawNumber(); % Leyes reales; no duplicar por el transporte 4+4.
burst_size = n_samples * n_channels * n_focal_law * n_images_burst; % Muestras int16 de una rafaga, tanto para 128 como 256.
fnyq=62.5/2;




%% Acquisition loop

% Prepare figure
if ~exist('h_figure', 'var') || ~isvalid(h_figure)
    h_figure = figure('visible','on');
    hButtonStop = uicontrol('Style', 'pushbutton', 'String', 'STOP',...
        'Position', [20 20 100 40], 'Callback', 'setappdata(gcbf, ''stopFlag'', 1)');
    set(h_figure, 'CloseRequestFcn', @closeFigCallback);
    imagesc(rand(5)); colormap gray;
end
setappdata(h_figure, 'stopFlag', 0);


% La copia usa la direccion PCIe; no se reserva un puntero auxiliar sin uso.

timeout_ms = 3000;

PEAK_NOISE_TYPICAL = 160;
RMS_NOISE_TYPICAL = 40;

result = ST2_Start(1);
if (result < 0)
    ST2_CloseSys();
    return;
end

burst_counter = 0;
flag_end = false;
try
    while (flag_end == false)
        
        [n_acq_images, address, idx_burst, timestamp, n_img_buffer] = PCIe_GetBufferAddress_Burst(timeout_ms);
        if (n_acq_images < 0)
            flag_end = true;
        else
            if (n_acq_images > 0)
                burst_counter = burst_counter + 1;
                fprintf("\r(%d) TimeStamp: %d - N. Images Buffer: %d - N. Images Availables: %d\r",idx_burst, timestamp, n_img_buffer, n_acq_images);
                
                whos rf
                
                rf=copyBufferToMatlab(address,burst_size);
                PCIe_FreeBufferAddress(n_acq_images);
                if (ST2_GetPauseAfterBurst() == 1)
                    ST2_Continue();
                    fprintf("\rCONTINUE!");
                end
                
                rf=reshape(rf,n_samples,n_channels,n_focal_law,n_images_burst);
                
                img=rf(:,:,1,1);
              
                
                [noise_std,noise_peak]=noise_meas(img,0);
                
                subplot(4,1,1)
                bar(1:n_channels,noise_peak); % Un valor por canal del equipo.
                axis([1 n_channels 0 350]); % Eje adaptable a cuatro u ocho bases.
                hold on; plot([1 n_channels],[PEAK_NOISE_TYPICAL PEAK_NOISE_TYPICAL],'r');hold off; % Referencia en todos los canales.
                title(sprintf('peak noise average %d (typical = %d w/o array)', round(mean(noise_peak)), PEAK_NOISE_TYPICAL));                
                
                subplot(4,1,2)
                bar(1:n_channels,noise_std); % Un valor RMS por canal.
                axis([1 n_channels 0 100]); % Eje adaptable al equipo.
                hold on; plot([1 n_channels],[RMS_NOISE_TYPICAL RMS_NOISE_TYPICAL],'r');hold off; % Referencia en todos los canales.
                title(sprintf('rms noise %d (typical = %d w/o array)', round(mean(noise_std)), RMS_NOISE_TYPICAL));                
                xlabel('Channel')
                
                
                subplot(4,1,3)
                avg_fft = mean(abs(fft(img)),2);
                m_fft = mean(avg_fft);
                plot([-fnyq:2*fnyq/(n_samples-1):fnyq],fftshift(avg_fft));
                axis([-fnyq, fnyq, 0, 2.5*m_fft])
                xlabel('f (MHz)');
                
                subplot(4,1,4)
                imagesc(img);
                caxis([-500 500]);
                colorbar;
                xlabel('Channel')
                ylabel('samples')
                drawnow;
                
                
            elseif (~acquisition_mode_continuous && burst_counter >= burst_number)
                flag_end = true;
            
            else
                %disp('warning :: n_acq_images = 0');
            end
        end
        drawnow;
        
        % Check if STOP button was pressed
        if getappdata(h_figure, 'stopFlag') == 1
            flag_end = true;
        end
        
        % Check if the window was clossed
        if getappdata(h_figure, 'isClosed') == 1
            flag_end = true;
        end
    end
    
catch ME
    fprintf('Error inside acquisition loop line %d \n',ME.stack(end).line);
    disp(ME.message);               % Muestra el mensaje de error
end


%% Stop acquisition and close connection

ST2_Stop();
CloseSys();


%% Auxiliar function when figure is closed

function closeFigCallback(src, ~)
setappdata(src, 'isClosed', 1);  % Cambiar la variable de control
delete(src);  % Cerrar la figura
end
